class AdductParser(StringParser):
    '''A buffer which accumulates tokens related to adducts until it is asked to parse them into
    a list of [(str, int)] tuples, where the first element is the adduct name
    and the second element is the number of adducts of that type.
    '''
    token_pattern = re.compile(r'(?P<number>[+-]?\d*)(?P<adduct>[A-Za-z]+)(?P<charge>\d*[+-])')
    token_pattern2 = re.compile(r'(?P<adduct>[A-Za-z]+):[zZ](?P<charge>(-|\+)\d+)(?:\^(?P<number>\d+))?')

    def parse_form1(self, token: str) -> Optional[Tuple[str, int, int]]:
        parsed = self.token_pattern.match(token)
        if not parsed:
            return None
        gdict = parsed.groupdict()
        if gdict['adduct'] == 'e':
            adduct = 'e-'
        else:
            adduct = gdict['adduct']
        if gdict['number'] == '+' or gdict['number'] == '':
            number = 1
        elif gdict['number'] == '-':
            number = -1
        else:
            number = int(gdict['number'])
        charge = int(gdict['charge'][:-1]) if gdict['charge'][:-1] else 1
        if gdict['charge'][-1] == '-':
            charge = -charge
        return (adduct, charge, number)

    def parse_form2(self, token: str):
        parsed = self.token_pattern2.match(token)
        if not parsed:
            return None
        gdict = parsed.groupdict()
        if gdict['adduct'] == 'e':
            adduct = 'e-'
        else:
            adduct = gdict['adduct']
        if gdict['number'] == '+' or gdict['number'] == '':
            number = 1
        elif gdict['number'] == '-':
            number = -1
        elif gdict['number'] is not None:
            number = int(gdict['number'])
        else:
            number = 1
        charge = int(gdict['charge']) if gdict['charge'] else 1
        return (adduct, charge, number)

    def process(self):
        value = []
        for token in self.tokenize():
            if not isinstance(token, str):
                token = ''.join(token)
            try:
                adduct = self.parse_form1(token)
                if not adduct:
                    adduct = self.parse_form2(token)
                if not adduct:
                    raise ProFormaError(
                        "Invalid adduct token {!r} in {!r}".format(token, self.buffer)
                    )
                value.append(Adduct(*adduct))
            except AttributeError:
                raise ProFormaError("Invalid adduct token {!r} in {!r}".format(token, self.buffer))
        return value


class TagParser(TokenBuffer[TagBase]):
    '''A buffer which accumulates tokens until it is asked to parse them into
    :class:`TagBase` instances.

    Implements a subset of the Sequence protocol.

    Attributes
    ----------
    buffer: list
        The list of tokens accumulated since the last parsing.
    group_ids: set
                self.state,
            )

    def handle_post_tag_after(self, c: str):
        if c == "/":
            self.state = CHARGE_START
            self.charge_buffer = NumberParser()
        elif c == "+":
            raise ProFormaError(
                f"Error In State {self.state}, {c} found at index {self.i}. Chimeric representation not supported",
                self.i,
                self.state,
            )

    def handle_charge_start(self, c: str):
        if c in "+-":
            self.charge_buffer.append(c)
            self.state = CHARGE_NUMBER
        elif c.isdigit():
            self.charge_buffer.append(c)
            self.state = CHARGE_NUMBER
        elif c == "/":
            self.state = ParserStateEnum.inter_chain_cross_link_start
            raise ProFormaError(
                "Inter-chain cross-linked peptides are not yet supported",
                self.i,
                self.state,
            )
        elif c == '[':
            self.state = ParserStateEnum.charge_state_adduct_start
        else:
            raise ProFormaError(
                f"Error In State {self.state}, unexpected {c} found at index {self.i}",
                self.i,
                self.state,
            )

    def handle_charge_number(self, c: str):
        if c.isdigit():
            self.charge_buffer.append(c)
        elif c == "[":
            self.state = ADDUCT_START
            self.adduct_buffer = AdductParser()
        else:
            raise ProFormaError(
                f"Error In State {self.state}, unexpected {c} found at index {self.i}",
                self.i,
                self.state,
            )

    def handle_adduct_start(self, c: str):
        if c.isdigit() or c in "+:-" or c.isalpha():
            self.adduct_buffer.append(c)
        elif c == ",":
            self.adduct_buffer.bound()
        elif c == "]":
            self.state = ADDUCT_END

    def handle_adduct_end(self, c: str):
        if c == "+":
            raise ProFormaError(
                f"Error In State {self.state}, {c} found at index {self.i}. Chimeric representation not supported",
                self.i,
                self.state,
            )

    def handle_name_level(self, c: str):
        if c == '>' and self.name_level < 3:
            self.name_level += 1
        elif c == ')':
            self.names[self.name_level] = self.name_buffer()

The notation of charged formulas is only required to be supported for level 3-ProForma + glycans supporting readers.

## 11. Level 3-Proforma

Technical name: level 3-ProForma compliant

## 11.1 Charged formulas

Charges can be specified on chemical formulas using the following suffix ‘<formula>:z<charge>’. This allows localised charges to be defined. The mass of a charged formula is the mass of its constituents minus z times the mass of an electron.

## SEQUEN[Formula:Zn1:z+2]CE

If the reader also supports the glycan composition notation, section 10.2, charged glycan compositions can be defined using the same syntax:

SEQUEN[Glycan:{C8H13N1O5Na1:z+1}1Hex2]CE

## 11.2 Controlling placement of modifications

Protein modifications of unknown position can result in many combinations of possible locations. To add more knowledge into the placement of these modifications, and limit the number of possible combinations, there are four ways to control the exact placement of modifications of unknown position:

Position: a list of positions where this modification is allowed. The positions are written the same as global modifications, see 11.3.2. If this is not specified the allowed position SHOULD be the allowed positions as defined in the CV/ontology, see 6.2.1.4.
EPELVESGGGLAQP

11.4 Representation of multiple peptidoform ion assignments in chimeric spectra In bottom-up approaches, in the case of chimeric spectra, more than one peptidoform ion sequence MAY be potentially assigned to a single mass spectrum. In this case, multiple peptidoform ion sequences MUST be separated by the plus sign (+). Example:

EMEVEESPEK/2+ELVISLIVER/3

PEPTIDE+OTHERPEPTIDE

## 11.5 Representation of charges

The charge of a peptidoform ion can be specified after the definition. This specifies the charge of the peptidoform ion, excluding any local charges of elemental formulas (section 11.1). Any positive charges are defined as addition of protons H+, any negative charges are defined as addition of electrons e-.

## PEPTIDE/2

If the charge carriers are different, these can be defined instead of the global charge using the formula with charge notation (section 11.1). The charge carriers have to be enclosed by square brackets and if there are multiple they have to be separated by commas.

PEPTIDE/[Na:z+1]

PEPTIDE/[Na:z+1,H:z+1]

PEPTIDE/[[15N1]H4:z+1]

If a charge carrier is present multiple times the occurrence specifier from the unknown location modifications can be used.

## PEPTIDE/[Na:z+1^2]

If both localised charges and charge carriers are used all of these should be accounted for in the total charge of the peptidoform ion. The following examples have a total charge of +4.

PEPT[Formula:Zn:z+2]IDE/2

PEPT[Formula:Zn:z+2]IDE/[Na:z+1^2]

## 11.6 Ion notation

A MSn precursor can be defined using the corresponding entries in Unimod, such as ‘a-type-ion’ (UNIMOD:140), ‘b-type-ion’ (UNIMOD:2132), ‘c-type-ion’ (UNIMOD:2141), ‘x-type-ion’ (UNIMOD:2142), and ‘z-type-ion’ (UNIMOD:2143). ‘y-type-ion’ does not exist in Unimod because it does not amount to any mass differences, if needed this can be written with an ‘INFO’ tag.

PEPTID-[a-type-ion]/1

PEPTID-[b-type-ion]/1

[INFO:y-type-ion]-PEPTID/1

